---
// Command ddkstat reports on Drydock's LLM execution log.
package main

import (
	"os"

	"ddkstat/internal/cli"
)

func main() {
	os.Exit(cli.Run(os.Args[1:], os.Stdout, os.Stderr))
}
---
// Package cli parses ddkstat arguments and dispatches to the reports.
package cli

import (
	"flag"
	"fmt"
	"io"
)

// Exit codes returned by Run.
const (
	exitOK    = 0
	exitUsage = 2
)

// Run parses args, writes diagnostics to stderr, and returns the process exit code.
// Standard output carries only report output; no report is implemented in this foundation step,
// so every invocation that reaches dispatch is a usage error.
func Run(args []string, stdout, stderr io.Writer) int {
	fs := flag.NewFlagSet("ddkstat", flag.ContinueOnError)
	fs.SetOutput(stderr)
	if err := fs.Parse(args); err != nil {
		return exitUsage
	}
	if fs.NArg() == 0 {
		fmt.Fprintln(stderr, "usage: ddkstat <report> <log.jsonl>")
		return exitUsage
	}
	fmt.Fprintf(stderr, "error: report %q is not implemented\n", fs.Arg(0))
	return exitUsage
}
---
package cli

import (
	"bytes"
	"testing"
)

func TestRunExitCodes(t *testing.T) {
	tests := []struct {
		name string
		args []string
		want int
	}{
		{name: "no arguments is a usage error", args: nil, want: exitUsage},
		{name: "unknown flag is a usage error", args: []string{"-nope"}, want: exitUsage},
		{name: "unimplemented report is a usage error", args: []string{"summary", "log.jsonl"}, want: exitUsage},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var stdout, stderr bytes.Buffer
			got := Run(tt.args, &stdout, &stderr)
			if got != tt.want {
				t.Errorf("Run(%q) = %d, want %d", tt.args, got, tt.want)
			}
			if stdout.Len() != 0 {
				t.Errorf("Run(%q) wrote %q to stdout, want nothing", tt.args, stdout.String())
			}
		})
	}
}
